#Requires -Version 5.1
#
# 远程访问：内置网页服务 + 指令队列
# 本文件由 MuMuGuardApp.ps1 dot-source（共享同一 $script: 作用域）
#
# 设计要点：
#   1. 服务跑在独立 runspace，绝不碰界面对象
#   2. 状态由 UI 线程定时生成 JSON 快照，服务只读这个字符串（不跨线程读活对象）
#   3. 指令进并发队列，由 UI 线程的定时器取出执行 —— 和本地点按钮走同一套函数

$script:remotePs    = $null
$script:remoteRs    = $null
$script:remoteHandle = $null

function New-RemoteToken {
    $bytes = New-Object byte[] 16
    [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($bytes)
    return (($bytes | ForEach-Object { '{0:x2}' -f $_ }) -join '')
}

function Get-RemoteToken {
    $t = ''
    try { $t = [string]$script:cfg.RemoteToken } catch { }
    if (-not $t) {
        $t = New-RemoteToken
        try { $script:cfg.RemoteToken = $t; Save-Config } catch { }
    }
    return $t
}

function Get-RemoteUrls {
    $port = 8787
    try { if ($script:cfg.RemotePort) { $port = [int]$script:cfg.RemotePort } } catch { }
    $token = Get-RemoteToken
    $urls = @()
    try {
        foreach ($a in (Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue)) {
            if ($a.IPAddress -match '^(127\.|169\.254\.|198\.18\.)') { continue }
            $desc = ''
            try { $desc = (Get-NetAdapter -InterfaceIndex $a.InterfaceIndex -ErrorAction SilentlyContinue).InterfaceDescription } catch { }
            if ($desc -match 'VMware|VirtualBox|TAP-|Hyper-V|xxyun|Clash|Loopback|Meta Tunnel') { continue }
            $urls += [pscustomobject]@{
                Ip  = $a.IPAddress
                Url = "http://$($a.IPAddress):$port/?k=$token"
            }
        }
    } catch { }
    return $urls
}

# ---------------- 状态快照（UI 线程调用） ----------------
function Build-RemoteState {
    $list = @()
    try {
        foreach ($r in @($script:lastInstances)) {
            if (-not $r) { continue }
            $state = 'unknown'
            $extra = ''
            $wake = ''
            try {
                if ($r.PSObject.Properties.Name -contains 'Sleeping' -and $r.Sleeping) {
                    $state = 'sleep'
                    if ($r.WakeAt) { $wake = ([datetime]$r.WakeAt).ToString('HH:mm') }
                    if ($r.WakeAt) { try { $wakeAt = ([datetime]$r.WakeAt).ToString('yyyy-MM-ddTHH:mm:ss') } catch { } }
                    if ($r.SleepUpgrade) { $extra = [string]$r.SleepUpgrade }
                } elseif ($r.Online -eq $true) {
                    $state = 'run'
                    if ($r.UpLeft) { $extra = '剩 ' + [string]$r.UpLeft }
                } elseif ($r.Online -eq $false) {
                    $state = 'off'
                }
            } catch { }
            $list += [pscustomobject][ordered]@{
                i     = "$($r.Index)"
                name  = "$($r.Name)"
                state = $state
                wake  = $wake
                extra = $extra
                judge = "$($r.Judge)"
                mem   = [int]$r.Private
                cores = [double]$r.Cores
            }
        }
    } catch { }

    # 休眠中的实例进程已关闭，不会出现在上面的列表里，单独补进来
    try {
        $have = @{}
        foreach ($x in @($list)) { $have["$($x.i)"] = $true }
        foreach ($sl in @(Get-SleepList)) {
            $si = "$($sl.Index)"
            if (-not $si -or $have.ContainsKey($si)) { continue }
            $wk = ''; $ex = ''
            try { if ($sl.WakeAt) { $wk = ([datetime]$sl.WakeAt).ToString('HH:mm') } } catch { }
            if ($sl.WakeAt) { try { $wakeAt2 = ([datetime]$sl.WakeAt).ToString('yyyy-MM-ddTHH:mm:ss') } catch { } }
            try { if ($sl.Upgrade) { $ex = [string]$sl.Upgrade } } catch { }
            $sic = $null
            try { if ($script:instanceMap -and $script:instanceMap.ContainsKey($si)) { $sic = $script:instanceMap[$si] } } catch { }
            $nm = "实例 $si"
            try { $dn = Get-InstanceDisplayName -Config $sic -Aliases $script:cfg.Aliases; if ($dn) { $nm = "$dn" } } catch { }
            $list += [pscustomobject][ordered]@{
                i = $si; name = $nm; state = 'sleep'; wake = $wk; wakeAt = "$wakeAt2"; extra = $ex; judge = '' ; mem = 0; cores = 0
            }
        }
    } catch { }

    $hostInfo = [ordered]@{ used = 0; total = 0; avail = 0 }
    try {
        $mi = [MemInfo]::Get()
        $totalMB = [math]::Round($mi[0] / 1MB)
        $freeMB  = [math]::Round($mi[1] / 1MB)
        $hostInfo.total = $totalMB
        $hostInfo.avail = $freeMB
        $hostInfo.used  = $totalMB - $freeMB
    } catch { }

    $events = @()
    try {
        $csv = Get-LogFile
        if (Test-Path $csv) {
            $rows = @(Import-Csv $csv -ErrorAction Stop)
            $events = @($rows | Select-Object -Last 8 | ForEach-Object {
                $t = ''
                try { $t = ([datetime]$_.Time).ToString('HH:mm:ss') } catch { $t = [string]$_.Time }
                [pscustomobject][ordered]@{ t = $t; m = ([string]('{0} {1}' -f $_.Action, $_.Detail)).Trim() }
            })
        }
    } catch { }

    $obj = [ordered]@{
        v         = 1
        ts        = [int64](([datetime]::UtcNow - (New-Object datetime 1970,1,1,0,0,0,([DateTimeKind]::Utc))).TotalSeconds)
        guard     = [bool]$script:guardRunning
        sleep     = [bool]$script:cfg.AutoSleep
        host      = $hostInfo
        instances = $list
        events    = $events
    }
    try { return ($obj | ConvertTo-Json -Depth 6 -Compress) } catch { return '{}' }
}

# ---------------- 服务端脚本（后台 runspace 运行） ----------------
$script:remoteServerScript = {
    param($sync, $port, $token, $root)

    $listener = $null
    try {
        $listener = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Any, $port)
        $listener.Start()
        $sync.ServerError = ''
    } catch {
        $sync.ServerError = $_.Exception.Message
        return
    }

    function Read-Req($client) {
        $stream = $client.GetStream()
        $client.ReceiveTimeout = 4000
        $buffer = New-Object byte[] 8192
        $sb = New-Object System.Text.StringBuilder
        $deadline = (Get-Date).AddSeconds(4)
        $headEnd = -1
        $need = 0
        while ((Get-Date) -lt $deadline) {
            $text = $sb.ToString()
            if ($headEnd -lt 0) {
                $idx = $text.IndexOf("`r`n`r`n")
                if ($idx -ge 0) {
                    $headEnd = $idx + 4
                    if ($text -match '(?i)Content-Length:\s*(\d+)') { $need = [int]$Matches[1] }
                }
            }
            if ($headEnd -ge 0 -and ($sb.Length - $headEnd) -ge $need) { break }
            if (-not $stream.DataAvailable) { Start-Sleep -Milliseconds 15; continue }
            $n = $stream.Read($buffer, 0, $buffer.Length)
            if ($n -le 0) { break }
            [void]$sb.Append([System.Text.Encoding]::UTF8.GetString($buffer, 0, $n))
        }
        return $sb.ToString()
    }
    function Send-Res($client, $code, $ctype, $body) {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($body)
        $reason = switch ($code) { 200 { 'OK' } 401 { 'Unauthorized' } 404 { 'Not Found' } 405 { 'Method Not Allowed' } default { 'OK' } }
        $head = "HTTP/1.1 $code $reason`r`nContent-Type: $ctype`r`nContent-Length: $($bytes.Length)`r`nCache-Control: no-store`r`nConnection: close`r`n`r`n"
        $hb = [System.Text.Encoding]::ASCII.GetBytes($head)
        $stream = $client.GetStream()
        $stream.Write($hb, 0, $hb.Length)
        $stream.Write($bytes, 0, $bytes.Length)
        $stream.Flush()
    }

    while ($true) {
        if ($sync.Stop) { break }
        $client = $null
        try { $client = $listener.AcceptTcpClient() } catch { break }
        try {
            $req = Read-Req $client
            $first = ($req -split "`r`n")[0]
            $method = 'GET'; $path = '/'
            if ($first -match '^(\w+)\s+(\S+)') { $method = $Matches[1]; $path = $Matches[2] }

            $query = ''
            if ($path -match '\?(.*)$') { $query = $Matches[1]; $path = $path -replace '\?.*$', '' }

            $given = ''
            foreach ($kv in ($query -split '&')) {
                if ($kv -match '^k=(.*)$') { $given = [System.Uri]::UnescapeDataString($Matches[1]) }
            }
            if ($given -ne $token) {
                Send-Res $client 401 'text/plain; charset=utf-8' 'TOKEN'
                continue
            }

            if ($path -eq '/' -or $path -eq '/index.html') {
                Send-Res $client 200 'text/html; charset=utf-8' $sync.RemotePage
            }
            elseif ($path -eq '/api/state') {
                $state = [string]$sync.RemoteState
                if (-not $state) { $state = '{}' }
                Send-Res $client 200 'application/json; charset=utf-8' $state
            }
            elseif ($path -eq '/api/action' -and $method -eq 'POST') {
                $body = ''
                if ($req -match "\r\n\r\n(.*)$") { $body = $Matches[1] }
                $cmd = $null
                try { $cmd = $body | ConvertFrom-Json } catch { }
                if (-not $cmd -or -not $cmd.cmd) {
                    Send-Res $client 200 'application/json; charset=utf-8' '{"ok":false,"msg":"bad request"}'
                } else {
                    $item = [ordered]@{ cmd = "$($cmd.cmd)"; i = "$($cmd.i)"; at = (Get-Date).ToString('HH:mm:ss') }
                    [void]$sync.RemoteQueue.Enqueue([pscustomobject]$item)
                    Send-Res $client 200 'application/json; charset=utf-8' '{"ok":true}'
                }
            }
            else {
                Send-Res $client 404 'text/plain; charset=utf-8' 'not found'
            }
        } catch { }
        finally { try { $client.Close() } catch { } }
    }
    try { $listener.Stop() } catch { }
}

# ---------------- 页面 ----------------
function Get-RemotePage {
    return @'
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#17171A">
<title>MuMuGuard</title>
<style>
  :root{--bg:#17171A;--card:#2B2B30;--line:rgba(255,255,255,.10);--text:#F2F2F5;--sub:#9E9EA6;--dim:#6E6E78;--green:#34C759;--amber:#FF9F0A;--blue:#0A84FF;--red:#FF453A}
  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
  html,body{width:100%;overflow-x:hidden}
  body{margin:0 auto;background:var(--bg);color:var(--text);font:15px/1.5 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;padding:16px 16px 26px;max-width:520px}
  header{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
  .brand{display:flex;align-items:center;gap:9px;font-size:17px;font-weight:600}
  .brand .logo{width:30px;height:30px;border-radius:9px;overflow:hidden;background:#3A3A42;display:block}
  .brand .logo img{width:100%;height:100%;object-fit:cover;display:block}
  .pill{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--sub);background:rgba(255,255,255,.06);padding:5px 10px;border-radius:20px}
  .dot{width:6px;height:6px;border-radius:50%;background:var(--green)}
  .dot.off{background:var(--dim)}
  .card{max-width:100%;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:2px 12px;margin-bottom:12px}
  .title{font-size:11px;color:var(--dim);padding:10px 2px 2px}
  .row{display:flex;align-items:center;gap:10px;padding:10px 0}
  .row+.row{border-top:1px solid var(--line)}
  .ico{width:30px;height:30px;border-radius:8px;flex:0 0 30px;background:#3A3A42 url(data:image/x-;base64,) center/cover}
  .who{flex:1;min-width:0}
  .name{font-size:14px}
  .meta{font-size:11px;color:var(--dim);margin-top:2px}
  .tag{font-size:10px;padding:3px 8px;border-radius:20px;white-space:nowrap;background:rgba(255,255,255,.08);color:var(--sub)}
  .tag.run{background:rgba(52,199,89,.16);color:var(--green)}
  .tag.sleep{background:rgba(255,159,10,.16);color:var(--amber)}
  .tag.off{background:rgba(255,255,255,.08);color:var(--sub)}
  .bar{height:5px;border-radius:3px;background:rgba(255,255,255,.14);overflow:hidden;margin-top:2px}
  .bar>i{display:block;height:100%;background:var(--blue);border-radius:3px;transition:width .4s}
  .bar.hi>i{background:var(--amber)}
  .kv{display:flex;justify-content:space-between;font-size:11px;color:var(--dim);padding:8px 0 12px}
  .ev{font-size:11px;color:var(--sub);padding:8px 0;border-top:1px solid var(--line);font-variant-numeric:tabular-nums}
  .ev:first-child{border-top:0}
  .ev b{color:var(--dim);font-weight:400;margin-right:8px}
  .ev.warn{color:var(--amber)}.ev.err{color:#FF8078}
  .empty{color:var(--dim);font-size:12px;padding:10px 0}
  .btns{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:4px 0 12px}
  button{appearance:none;border:1px solid var(--line);background:rgba(255,255,255,.06);color:var(--text);border-radius:11px;padding:12px 8px;font-size:13px;font-family:inherit}
  button:active{background:rgba(255,255,255,.12)}
  button.warn{color:var(--amber)}
  button.danger{color:var(--red)}
  button:disabled{opacity:.45}
  .sw{display:inline-flex;align-items:center;margin-left:auto}
  .sw i{width:36px;height:21px;border-radius:11px;background:rgba(255,255,255,.14);position:relative;transition:background .2s;display:block}
  .sw i::after{content:"";position:absolute;top:2px;left:2px;width:17px;height:17px;border-radius:50%;background:#fff;transition:transform .2s}
  .sw.on i{background:var(--green)}
  .sw.on i::after{transform:translateX(15px)}
  .toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%);background:#33333A;border:1px solid var(--line);color:var(--text);padding:9px 16px;border-radius:11px;font-size:13px;opacity:0;transition:opacity .2s;pointer-events:none}
  .toast.show{opacity:1}
  footer{text-align:center;color:var(--dim);font-size:11px;margin-top:14px}
  .err{color:var(--red);font-size:12px;padding:6px 0}
  .sub{padding:0 2px 12px;font-size:11.5px;color:var(--dim)}
  .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:12px}
  .stat{background:var(--card);border:1px solid var(--line);border-radius:11px;padding:9px 6px;text-align:center}
  .stat b{display:block;font-size:19px;font-weight:600;line-height:1.1}
  .stat span{display:block;font-size:9.5px;color:var(--dim);margin-top:3px}
  .c-run{color:var(--green)}.c-sleep{color:var(--amber)}.c-off{color:var(--sub)}
  .rt{text-align:right;min-width:46px}
  .rt b{display:block;font-size:13px;font-weight:500}
  .rt span{display:block;font-size:9.5px;color:var(--dim);margin-top:1px}
  button{display:flex;align-items:center;justify-content:center;gap:6px}
  button .bdot{width:6px;height:6px;border-radius:50%;background:var(--green);flex:0 0 6px}
  button .bdot.orange{background:var(--amber)}
  button.primary{background:#F2F2F5;color:#17171A;border-color:#F2F2F5;font-weight:600}
  .memrow{display:flex;align-items:flex-end;padding:8px 0 0}
  .memrow b{font-size:24px;font-weight:600;line-height:1}
  .memrow em{font-style:normal;font-size:11px;color:var(--dim);margin:0 0 3px 5px}
</style>
</head>
<body>
<header>
  <div class="brand"><span class="logo"><img src="data:image/x-icon;base64," alt=""></span>MuMuGuard</div>
  <div class="pill"><span class="dot" id="dot"></span><span id="guardText">连接中…</span></div>
</header>

<div class="sub" id="subLine">正在读取…</div>

<div class="stats">
  <div class="stat"><b id="statTotal">–</b><span>总数</span></div>
  <div class="stat"><b id="statRun" class="c-run">–</b><span>运行</span></div>
  <div class="stat"><b id="statSleep" class="c-sleep">–</b><span>休眠</span></div>
  <div class="stat"><b id="statOff" class="c-off">–</b><span>关闭</span></div>
</div>

<div class="card"><div class="title">实例</div><div id="instances"><div class="empty">正在读取…</div></div></div>

<div class="card">
  <div class="title">操作</div>
  <div class="btns">
    <button id="bGuard"><i class="bdot"></i><span>停止看护</span></button>
    <button id="bSleep"><i class="bdot orange"></i><span>自动休眠 关</span></button>
    <button id="bClean">立即清理</button>
    <button id="bWakeAll" class="primary">唤醒全部</button>
  </div>
</div>

<div class="card">
  <div class="title">主机内存</div>
  <div class="bar" id="membar"><i id="memfill" style="width:0%"></i></div>
  <div class="memrow"><b id="memBig">–</b><em id="memTotal">/ --</em></div>
  <div class="kv"><span id="memUsed">--</span><span id="memAvail">--</span></div>
</div>

<div class="card"><div class="title">最近事件</div><div id="events"><div class="empty">暂无</div></div></div>

<footer>每 2 秒刷新 · 数据仅在本机与手机之间</footer>
<div class="toast" id="toast"></div>

<script>
const K = new URLSearchParams(location.search).get('k') || '';
let lastState = null;
function wakeInfo(it){
  const raw = it.wakeAt || '';
  if (!raw) return null;
  const d = new Date(raw);
  if (isNaN(d.getTime())) return null;
  const now = new Date();
  const d0 = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  const n0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const days = Math.round((d0 - n0) / 86400000);
  const hm = ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);
  let main;
  if (days === 0) main = '今天 ' + hm;
  else if (days === 1) main = '明天 ' + hm;
  else if (days === -1) main = '昨天 ' + hm;
  else main = (d.getMonth() + 1) + '月' + d.getDate() + '日 ' + hm;
  const mins = Math.round((d - now) / 60000);
  let sub;
  if (mins <= 0) sub = '到时间了';
  else if (mins < 60) sub = '还有 ' + mins + ' 分钟';
  else if (mins < 1440) sub = '还有 ' + Math.floor(mins / 60) + ' 小时 ' + (mins % 60) + ' 分';
  else sub = '还有 ' + Math.floor(mins / 1440) + ' 天 ' + Math.floor((mins % 1440) / 60) + ' 小时';
  return { main: main, sub: sub };
}
const EVMAP = {CLEAN_CEF:'清理', SLEEP:'休眠', SLEEP_BG:'后台休眠', WAKE_MANUAL:'手动唤醒', WAKE_LATE:'补唤醒', AUTO_RECOVER:'自动恢复', AUTO_RESTART:'自动重启', RECOVER_OK:'恢复成功', RECOVER_FAIL:'恢复失败', LOW_MEM:'内存偏低', ALERT_MEM:'内存告警', ALERT_SCRIPT:'脚本告警', CEF_HIGH:'CEF 偏高', ROOT_FAIL:'权限失败', SLEEP_FAIL:'休眠失败'};
function evText(s){ return String(s==null?'':s).replace(/^([A-Z][A-Z_]+)\s+/, function(x, c){ return (EVMAP[c] || c) + ' '; }); }

function esc(s){ return String(s==null?'':s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function toast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg; t.classList.add('show');
  clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove('show'), 1600);
}

async function act(cmd, i){
  if(cmd === 'guard' || cmd === 'sleep'){
    const now = lastState ? (cmd === 'guard' ? lastState.guard : lastState.sleep) : null;
    if(now === null) return;
  }
  try{
    const r = await fetch('/api/action?k=' + encodeURIComponent(K), {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify(i ? {cmd:cmd, i:i} : {cmd:cmd})
    });
    const j = await r.json();
    toast(j.ok ? '已发送' : '发送失败');
    setTimeout(tick, 400);
  }catch(e){ toast('网络错误'); }
}

async function tick(){
  try{
    const r = await fetch('/api/state?k=' + encodeURIComponent(K), {cache:'no-store'});
    if(!r.ok) throw new Error('HTTP ' + r.status);
    const d = await r.json();
    lastState = d;

    const dot = document.getElementById('dot');
    dot.className = 'dot' + (d.guard ? '' : ' off');
    const gt = document.getElementById('guardText');
    gt.textContent = d.guard ? '看护中' : '已停止';
    gt.style.color = d.guard ? '' : 'var(--dim)';

    document.getElementById('bGuard').innerHTML = '<i class="bdot"></i><span>' + (d.guard ? '停止看护' : '启动看护') + '</span>';
    document.getElementById('bSleep').innerHTML = '<i class="bdot orange"></i><span>休眠 ' + (d.sleep ? '开' : '关') + '</span>';
    document.getElementById('bSleep').className = d.sleep ? '' : 'warn';

const _list = d.instances || [];
const _run = _list.filter(x => x.state === "run").length;
const _sleep = _list.filter(x => x.state === "sleep").length;
const _off = Math.max(0, _list.length - _run - _sleep);
const _sub = document.getElementById("subLine"); if(_sub) _sub.textContent = _list.length + " 个实例 · " + _run + " 个运行 · " + _sleep + " 个休眠";
const _st = document.getElementById("statTotal"); if(_st) _st.textContent = _list.length;
const _sr = document.getElementById("statRun"); if(_sr) _sr.textContent = _run;
const _ss = document.getElementById("statSleep"); if(_ss) _ss.textContent = _sleep;
const _so = document.getElementById("statOff"); if(_so) _so.textContent = _off;
    const box = document.getElementById('instances');
    if(!d.instances || !d.instances.length){
      box.innerHTML = '<div class="empty">没有检测到实例</div>';
    } else {
      box.innerHTML = d.instances.map(it => {
        let tag = '离线', cls = 'off', meta = '实例 ' + esc(it.i);
        if(it.state === 'run'){ tag = '运行中'; cls = 'run'; if(it.extra) meta = esc(it.extra); }
        else if(it.state === 'sleep'){ tag = '休眠'; cls = 'sleep'; if(it.extra) meta = esc(it.extra); }
        else if(it.state === 'unknown'){ tag = '未知'; cls = 'off'; }
        if(it.judge && it.judge !== '正常'){ meta += ' · ' + esc(it.judge); }
        return '<div class="row"><div class="ico"></div><div class="who"><div class="name">' + esc(it.name) + '</div><div class="meta">' + meta + '</div></div>' + '<div class="rt"><b>' + esc(it.state === 'sleep' ? ((wakeInfo(it) || {}).main || it.wake || '—') : (it.state === 'run' && it.extra ? String(it.extra).replace(/^剩\s*/, '') : '—')) + '</b><span>' + (it.state === 'sleep' ? ((wakeInfo(it) || {}).sub || '唤醒') : (it.state === 'run' ? '剩余' : '无任务')) + '</span></div>' +
               '<div class="tag ' + cls + '">' + esc(tag) + '</div></div>';
      }).join('');
    }

    const used = d.host ? d.host.used : 0, total = d.host ? d.host.total : 0;
    const pct = total ? Math.min(100, Math.round(used / total * 100)) : 0;
    document.getElementById('memfill').style.width = pct + '%';
    document.getElementById('membar').className = 'bar' + (pct >= 85 ? ' hi' : '');
    document.getElementById('memUsed').textContent  = '已用 ' + (used/1024).toFixed(1) + ' GB';
const _mb = document.getElementById("memBig"); if(_mb) _mb.textContent = (used/1024).toFixed(1);
const _ma = document.getElementById("memAvail"); if(_ma) _ma.textContent = "可用 " + ((total-used)/1024).toFixed(1) + " GB";
    document.getElementById('memTotal').textContent = '共 ' + (total/1024).toFixed(1) + ' GB';

    const ev = document.getElementById('events');
    if(!d.events || !d.events.length){
      ev.innerHTML = '<div class="empty">今天还没有事件</div>';
    } else {
      ev.innerHTML = d.events.map(e => {
        let cls = 'ev'; const m = evText(e.m);
        if(/失败|异常|掉线|未运行|错误/.test(m)) cls += ' err';
        else if(/告警|偏高|接近|不足/.test(m)) cls += ' warn';
        return '<div class="' + cls + '"><b>' + esc(e.t) + '</b>' + esc(m) + '</div>';
      }).join('');
    }
  }catch(err){
    document.getElementById('guardText').textContent = '连接断开';
    document.getElementById('dot').className = 'dot off';
  }
}

document.getElementById('bGuard').onclick   = () => act('guard');
document.getElementById('bSleep').onclick   = () => act('sleep');
document.getElementById('bClean').onclick   = () => { if(confirm('立即清理？')) act('clean'); };
document.getElementById('bWakeAll').onclick = () => { if(confirm('唤醒所有休眠实例？')) act('wakeall'); };

tick();
setInterval(tick, 2000);
</script>
</body>
</html>
'@
}

# ---------------- 启停 ----------------
function Start-RemoteServer {
    if ($script:remoteHandle) { return $true }
    $port = 8787
    try { if ($script:cfg.RemotePort) { $port = [int]$script:cfg.RemotePort } } catch { }
    $token = Get-RemoteToken

    $sync = $script:adbSync
    $sync | Add-Member -NotePropertyName RemoteState -NotePropertyValue '{}' -Force
    $sync | Add-Member -NotePropertyName RemotePage -NotePropertyValue (Get-RemotePage) -Force
    $sync | Add-Member -NotePropertyName RemoteQueue -NotePropertyValue (New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]') -Force
    $sync | Add-Member -NotePropertyName RemotePort -NotePropertyValue $port -Force
    $sync | Add-Member -NotePropertyName RemoteStop -NotePropertyValue $false -Force
    $sync | Add-Member -NotePropertyName ServerError -NotePropertyValue '' -Force

    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = 'MTA'
    $rs.ThreadOptions = 'ReuseThread'
    $rs.Open()
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript($script:remoteServerScript).AddArgument($sync).AddArgument($port).AddArgument($token).AddArgument($Root)
    $handle = $ps.BeginInvoke()

    $script:remotePs = $ps
    $script:remoteRs = $rs
    $script:remoteHandle = $handle
    Start-Sleep -Milliseconds 300
    if ($sync.ServerError) {
        Write-Diag "远程服务启动失败: $($sync.ServerError)"
        Stop-RemoteServer
        return $false
    }
    Write-Diag "远程服务已启动，端口 $port"
    return $true
}

function Stop-RemoteServer {
    try { if ($script:adbSync) { $script:adbSync.RemoteStop = $true } } catch { }
    try { if ($script:remotePs) { [void]$script:remotePs.Stop() } } catch { }
    try { if ($script:remotePs) { $script:remotePs.Dispose() } } catch { }
    try { if ($script:remoteRs) { $script:remoteRs.Close(); $script:remoteRs.Dispose() } } catch { }
    $script:remotePs = $null
    $script:remoteRs = $null
    $script:remoteHandle = $null
}

# ---------------- 指令处理（UI 线程） ----------------
function Invoke-RemoteCommands {
    $sync = $script:adbSync
    if (-not $sync -or -not ($sync.PSObject.Properties.Name -contains 'RemoteQueue')) { return }
    $q = $sync.RemoteQueue
    $obj = $null
    $n = 0
    while ($n -lt 8 -and $q.TryDequeue([ref]$obj)) {
        $n++
        try {
            switch ("$($obj.cmd)") {
                'guard'   { Set-GuardState; Write-Diag '远程：切换看护' }
                'sleep'   {
                    $script:cfg.AutoSleep = -not [bool]$script:cfg.AutoSleep
                    Save-Config; Update-SleepButton
                    Write-Diag ("远程：升级休眠 = {0}" -f $script:cfg.AutoSleep)
                }
                'clean'   { Invoke-GuardCleanup; Write-Diag '远程：立即清理' }
                'restart' {
                    if ($obj.i) { Start-InstanceRecover "$($obj.i)"; Write-Diag "远程：重启实例 $($obj.i)" }
                }
                'wakeall' { try { Start-Waker } catch { }; Write-Diag '远程：全部唤醒' }
                default   { write-Diag "远程：未知指令 $($obj.cmd)" }
            }
        } catch {
            Write-Diag "远程指令执行失败（$($obj.cmd)）: $($_.Exception.Message)"
        }
    }
    # 快照交给服务线程
    try { $sync.RemoteState = Build-RemoteState } catch { }
}

# ---------------- 手机访问窗口（XAML 构建，和设置面板同一套做法，DPI 才正常） ----------------
$script:remoteXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="手机访问" Width="404" SizeToContent="Height"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False">
  <Window.Resources>
    <Style x:Key="FlatBtn" TargetType="Button">
      <Setter Property="Foreground" Value="#F2F2F5"/>
      <Setter Property="Background" Value="#1AFFFFFF"/>
      <Setter Property="FontSize" Value="11.5"/>
      <Setter Property="Padding" Value="0,9,0,9"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border CornerRadius="9" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="SegBtn" TargetType="Button">
      <Setter Property="Foreground" Value="#6E6E78"/>
      <Setter Property="Background" Value="Transparent"/>
      <Setter Property="FontSize" Value="11"/>
      <Setter Property="Padding" Value="12,5,12,5"/>
      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border CornerRadius="7" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
  </Window.Resources>
  <Border CornerRadius="14" Background="#232327" BorderBrush="#33FFFFFF" BorderThickness="1">
    <StackPanel Margin="22,18,22,18">
      <Grid>
        <StackPanel Orientation="Horizontal">
          <TextBlock Text="手机访问" FontSize="15" FontWeight="SemiBold" Foreground="#F2F2F5" VerticalAlignment="Center"/>
          <Border Background="#1AFFFFFF" CornerRadius="6" Padding="7,2,7,3" Margin="9,0,0,0" VerticalAlignment="Center">
            <TextBlock x:Name="TxtState" Text="已开启" FontSize="9.5" Foreground="#6E6E78"/>
          </Border>
        </StackPanel>
        <Border HorizontalAlignment="Right" VerticalAlignment="Center" Background="#1AFFFFFF" CornerRadius="8" Padding="2">
          <StackPanel Orientation="Horizontal">
            <Button x:Name="BtnModeLan" Content="局域网" Style="{StaticResource SegBtn}"/>
            <Button x:Name="BtnModeWan" Content="出门用" Style="{StaticResource SegBtn}"/>
          </StackPanel>
        </Border>
      </Grid>

      <TextBlock x:Name="TxtHint" Foreground="#6E6E78" FontSize="10.5" TextWrapping="Wrap" Margin="0,10,0,14"/>

      <Border x:Name="QrBox" Width="196" Height="196" Background="White" CornerRadius="10" HorizontalAlignment="Center" Margin="0,0,0,12">
        <Image x:Name="ImgQr" Width="172" Height="172" Stretch="Uniform"/>
      </Border>

      <Border Background="#1A1A1E" CornerRadius="9" Padding="12,9" Margin="0,0,0,14">
        <Grid>
          <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <TextBlock x:Name="TxtUrl" Foreground="#9E9EA6" FontSize="10.5" TextTrimming="CharacterEllipsis" VerticalAlignment="Center"/>
          <Border x:Name="BtnCopy" Grid.Column="1" Background="#1AFFFFFF" CornerRadius="6" Padding="8,3" Margin="8,0,0,0" Cursor="Hand">
            <TextBlock Text="复制" FontSize="10" Foreground="#E6E6EC"/>
          </Border>
        </Grid>
      </Border>

      <Grid>
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="*"/><ColumnDefinition Width="8"/>
          <ColumnDefinition Width="*"/><ColumnDefinition Width="8"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <Button x:Name="BtnPower" Grid.Column="0" Style="{StaticResource FlatBtn}"/>
        <Button x:Name="BtnRefresh" Grid.Column="2" Content="刷新令牌" Style="{StaticResource FlatBtn}"/>
        <Button x:Name="BtnClose" Grid.Column="4" Content="关闭" Style="{StaticResource FlatBtn}" Background="#F2F2F5" Foreground="#1B1B1F"/>
      </Grid>
    </StackPanel>
  </Border>
</Window>
"@

function Show-RemoteDialog {
    if ($script:remoteDlg) {
        try { $script:remoteDlg.Activate() } catch { }
        return
    }
    $dlg = [Windows.Markup.XamlReader]::Parse((Convert-XamlTheme $script:remoteXaml))
    Set-ThemeResources $dlg (Get-ActiveTheme)
   if ($win -and $win.IsVisible) { try { $dlg.Owner = $win } catch { } }

    $hint     = $dlg.FindName('TxtHint')
    $qrBox    = $dlg.FindName('QrBox')
    $imgQr    = $dlg.FindName('ImgQr')
    $txtUrl   = $dlg.FindName('TxtUrl')
    $btnPower = $dlg.FindName('BtnPower')
    $btnRefresh = $dlg.FindName('BtnRefresh')
    $txtState  = $dlg.FindName('TxtState')
    $btnCopy   = $dlg.FindName('BtnCopy')
    if ($btnCopy) { $btnCopy.Add_MouseLeftButtonUp({ try { $t = $script:remoteDlg.FindName('TxtUrl'); if ($t -and $t.Text) { [System.Windows.Clipboard]::SetText($t.Text) } } catch { } }) }
    $rootDlg = $dlg.FindName('TxtTitle'); if (-not $rootDlg) { try { $dlg.FindName('TxtHint').Add_MouseLeftButtonDown({ $dlg.DragMove() }) } catch { } }
    $btnModeLan = $dlg.FindName('BtnModeLan')
    $btnModeWan = $dlg.FindName('BtnModeWan')

    $script:remoteMode = 'lan'

    $script:remoteRefreshUi = {
        $d = $script:remoteDlg
        if (-not $d) { return }
        $btnModeLan = $d.FindName('BtnModeLan')
        $btnModeWan = $d.FindName('BtnModeWan')
        $btnPower   = $d.FindName('BtnPower')
        $btnRefresh = $d.FindName('BtnRefresh')
        $hint       = $d.FindName('TxtHint')
        $qrBox      = $d.FindName('QrBox')
        $imgQr      = $d.FindName('ImgQr')
        $txtUrl     = $d.FindName('TxtUrl')

        $isLan = ($script:remoteMode -eq 'lan')
        $btnModeLan.Foreground = if ($isLan) { Brush '#F2F2F5' } else { Brush '#6E6E78' }
        $btnModeWan.Foreground = if ($isLan) { Brush '#6E6E78' } else { Brush '#F2F2F5' }
        $btnModeLan.Background = if ($isLan) { Brush '#33FFFFFF' } else { Brush '#00000000' }
        $btnModeWan.Background = if ($isLan) { Brush '#00000000' } else { Brush '#33FFFFFF' }
        $enabled = if ($isLan) { [bool]$script:cfg.RemoteEnabled } else { [bool]$script:cfg.OutboundEnabled }
        if ($isLan) {
            $hint.Text = '手机扫下面的二维码，或直接输入网址。同一 WiFi 下即可访问。'
        } else {
            $hint.Text = '出门在外也能用：手机打开下面的地址（走公共中转，不需要同一 WiFi）。'
        }
        $st = $d.FindName('TxtState')
        if ($st) { $st.Text = $(if ($enabled) { '已开启' } else { '未开启' }); $st.Foreground = $(if ($enabled) { Brush '#34C759' } else { Brush '#6E6E78' }) }

        if ($enabled) {
            $btnPower.Content = '停止服务'
            $btnRefresh.IsEnabled = $enabled
            if ($isLan) { $btnRefresh.Content = '刷新令牌' } else { $btnRefresh.Content = '重新配对' }
            if ($isLan) {
                $urls = @(Get-RemoteUrls)
                $url = ''
                if ($urls.Count -gt 0) { $url = $urls[0].Url }
                if ($url) {
                    $txtUrl.Text = $url
                    $qrBox.Visibility = 'Visible'
                    try { $imgQr.Source = New-QrBitmap $url 8 3 } catch { $imgQr.Source = $null }
                } else {
                    $txtUrl.Text = '没有找到可用的局域网地址'
                    $qrBox.Visibility = 'Collapsed'
                }
            } else {
                $url = Get-OutboundPageUrl
                $txtUrl.Text = $url
                $qrBox.Visibility = 'Visible'
                try { $imgQr.Source = New-QrBitmap $url 8 3 } catch { $imgQr.Source = $null }
            }
        } else {
            $btnPower.Content = '开启服务'
            $btnRefresh.IsEnabled = $false
            $txtUrl.Text = ''
            $qrBox.Visibility = 'Collapsed'
        }
    }

    $btnModeLan.Add_Click({ $script:remoteMode = 'lan'; & $script:remoteRefreshUi })
    $btnModeWan.Add_Click({ $script:remoteMode = 'wan'; & $script:remoteRefreshUi })
    $btnPower.Add_Click({
        try {
            if ($script:remoteMode -eq 'lan') {
                if ([bool]$script:cfg.RemoteEnabled) {
                    Stop-RemoteServer
                    $script:cfg.RemoteEnabled = $false
                } else {
                    $script:cfg.RemoteEnabled = $true
                    if (-not $script:cfg.RemoteToken) { $script:cfg.RemoteToken = New-RemoteToken }
                    if (-not (Start-RemoteServer)) { $script:cfg.RemoteEnabled = $false }
                }
            } else {
                if ([bool]$script:cfg.OutboundEnabled) {
                    Stop-Outbound
                    $script:cfg.OutboundEnabled = $false
                } else {
                    $script:cfg.OutboundEnabled = $true
                    if (-not (Get-OutboundUid)) { $script:cfg.OutboundUid = New-OutboundUid }
                    if (-not (Start-Outbound)) { $script:cfg.OutboundEnabled = $false }
                }
            }
            Save-Config
        } catch { Write-Diag "切换手机访问失败: $($_.Exception.Message)" }
        & $script:remoteRefreshUi
    })
    $btnRefresh.Add_Click({
        try {
            if ($script:remoteMode -eq 'lan') {
                $script:cfg.RemoteToken = New-RemoteToken
                Save-Config
                if ($script:cfg.RemoteEnabled) {
                    Stop-RemoteServer
                    [void](Start-RemoteServer)
                }
                Write-Diag '手机访问：令牌已刷新'
            } else {
                # 重新配对：换掉 uid 和密钥，旧二维码立刻作废
                Stop-Outbound
                $script:cfg.OutboundUid = New-OutboundUid
                $script:cfg.OutboundKey = New-OutboundKey
                Save-Config
                if ($script:cfg.OutboundEnabled) { [void](Start-Outbound) }
                Write-Diag '手机访问：已重新配对'
            }
        } catch { Write-Diag "刷新失败: $($_.Exception.Message)" }
        & $script:remoteRefreshUi
    })

    $dlg.FindName('BtnClose').Add_Click({ $dlg.Close() })
    $dlg.Add_Closed({ $script:remoteDlg = $null })
    try { $dlg.FindName('TxtTitle').Add_MouseLeftButtonDown({ try { $dlg.DragMove() } catch { } }) } catch { }

    $script:remoteDlg = $dlg
    & $script:remoteRefreshUi
    [void]$dlg.ShowDialog()
    # 面板是从 ShowDialog 里开的，直接 Show 容易被别的窗口压住，这里强制提到最前
    try {
        $dlg.Topmost = $true
        $dlg.Activate()
        $dlg.Focus()
        $dlg.Topmost = $false
        $dlg.Activate()
    } catch { }
    try { $dlg.Activate() } catch { }
}

